use crate::models::{AuthRequest, User};

pub fn get_user(id: u64) -> User {
    User { id, name: "anon".into() }
}

/// Protected route: returns the caller only when the token passes `check_auth`.
pub fn protected(req: &AuthRequest) -> Result<User, &'static str> {
    log_request("/protected");

    if !check_auth(&req.token) {
        return Err("unauthorized");
    }

    Ok(User { id: 0, name: "authorized".into() })
}

#[cfg(test)]
mod tests {
    use super::protected;
    use crate::models::AuthRequest;

    #[test]
    fn allows_valid_token() {
        let req = AuthRequest { token: "secret-token".into() };
        assert!(protected(&req).is_ok());
    }

    #[test]
    fn denies_invalid_token() {
        let req = AuthRequest { token: "nope".into() };
        assert_eq!(protected(&req), Err("unauthorized"));
    }
}
"}
